<template>
  <div class="issue-filters row items-center q-gutter-sm">
    <q-input
      :model-value="search"
      :label="$t('search')"
      outlined
      dense
      clearable
      class="filter-search"
      @update:model-value="(v) => $emit('update:search', v == null ? '' : String(v))"
    />
    <q-select
      :model-value="filters.status"
      :options="statusOptions"
      :label="$t('status')"
      outlined
      dense
      emit-value
      map-options
      clearable
      class="filter-select"
      @update:model-value="updateFilter('status', $event || '')"
    />
    <q-select
      :model-value="filters.priority"
      :options="priorityOptions"
      :label="$t('priority')"
      outlined
      dense
      emit-value
      map-options
      clearable
      class="filter-select"
      @update:model-value="updateFilter('priority', $event || '')"
    />
    <AssigneePicker
      :model-value="filters.assignee_id"
      :agents="agentAssigneeOptions"
      :humans="humanAssigneeOptions"
      :label="$t('assignee')"
      class="filter-select"
      @update:model-value="updateFilter('assignee_id', $event || '')"
    />
    <f-btn
      appearance="flat"
      icon="clear_all"
      :label="$t('clear')"
      size="sm"
      dense
      @click="$emit('clear')"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import AssigneePicker, { type AssigneeOption } from '../../shared/AssigneePicker.vue';
import {
  priorityOptions as buildPriorityOptions,
  statusOptions as buildStatusOptions,
} from '../../shared/docnet-labels';

export interface FilterValues {
  status: string;
  priority: string;
  type: string;
  assignee_id: string;
}

export interface AgentOption {
  id: string;
  name: string;
}

export interface HumanOption {
  id: string;
  name: string;
}

export default defineComponent({
  name: 'IssueFilters',
  components: { AssigneePicker },
  props: {
    filters: {
      type: Object as PropType<FilterValues>,
      required: true,
    },
    search: {
      type: String,
      default: '',
    },
    agents: {
      type: Array as PropType<AgentOption[]>,
      default: () => [],
    },
    humans: {
      type: Array as PropType<HumanOption[]>,
      default: () => [],
    },
  },
  emits: ['update:filters', 'update:search', 'clear'],
  computed: {
    statusOptions() {
      return buildStatusOptions(this.$t);
    },
    priorityOptions() {
      return buildPriorityOptions(this.$t);
    },
    agentAssigneeOptions(): AssigneeOption[] {
      return this.agents.map((a) => ({
        label: a.name,
        value: a.id,
        type: 'agent' as const,
      }));
    },
    humanAssigneeOptions(): AssigneeOption[] {
      return this.humans.map((h) => ({
        label: h.name,
        value: h.id,
        type: 'human' as const,
      }));
    },
  },
  methods: {
    updateFilter(key: string, value: string) {
      this.$emit('update:filters', {
        ...this.filters,
        [key]: value,
      });
    },
  },
});
</script>

