<template>
  <div class="docnet-issue-list">
    <!-- My Issues section -->
    <div v-if="myIssues.length > 0" class="q-mb-md">
      <div class="row items-center q-mb-sm">
        <q-icon name="person" size="18px" color="primary" class="q-mr-xs" />
        <span class="text-subtitle2 text-weight-medium">{{ $t('my_issues') }}</span>
        <q-badge class="q-ml-sm" color="primary" :label="myIssues.length" />
      </div>
      <div class="my-issues-grid">
        <q-card
          v-for="issue in myIssues"
          :key="issue.id"
          flat
          bordered
          class="my-issue-card cursor-pointer"
          @click="onIssueClick(issue)"
        >
          <q-card-section class="q-pa-sm">
            <div class="row items-center no-wrap q-mb-xs">
              <StatusBadge :status="issue.status" size="sm" />
              <PriorityIcon :priority="issue.priority" class="q-ml-sm" />
              <q-space />
              <span v-if="issue.mission_name" class="text-caption text-grey-6 ellipsis row items-center no-wrap q-gutter-xs" style="max-width: 120px">
                <q-badge v-if="titlePrefix(issue.mission_name)" color="blue-grey-3" text-color="blue-grey-9" :label="titlePrefix(issue.mission_name)" />
                <span>{{ titleDisplay(issue.mission_name) }}</span>
              </span>
            </div>
            <div class="text-body2 text-weight-medium ellipsis-2-lines">
              <q-badge v-if="titlePrefix(issue.title)" color="blue-grey-3" text-color="blue-grey-9" :label="titlePrefix(issue.title)" class="q-mr-xs" />
              {{ titleDisplay(issue.title) }}
            </div>
          </q-card-section>
        </q-card>
      </div>
      <q-separator class="q-mt-md" />
    </div>

    <!-- Toolbar: search + filters + view toggle + create button -->
    <div class="row items-center justify-between q-mb-md docnet-issue-toolbar">
      <IssueFilters
        :filters="filters"
        :search="searchQuery"
        :agents="agentOptions"
        :humans="humanOptions"
        class="docnet-issue-filters"
        @update:filters="onFiltersUpdate"
        @update:search="onSearchInput"
        @clear="onClearFilters"
      />
      <div class="row items-center q-gutter-sm" style="flex-shrink: 0">
        <q-btn
          dense
          flat
          no-caps
          class="docnet-group-btn"
          padding="6px 10px"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83Z"/><path d="m6.08 9.5-3.5 1.6a1 1 0 0 0 0 1.81l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83l-3.5-1.59"/><path d="m6.08 14.5-3.5 1.6a1 1 0 0 0 0 1.81l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83l-3.5-1.59"/></svg>
          <span class="q-ml-xs">{{ $t('group') }}</span>
          <q-menu>
            <q-list dense style="min-width: 150px">
              <q-item v-for="opt in groupOptions" :key="opt.value" clickable v-close-popup @click="groupBy = opt.value">
                <q-item-section>{{ opt.label }}</q-item-section>
                <q-item-section v-if="groupBy === opt.value" side>
                  <q-icon name="check" size="16px" color="primary" />
                </q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </q-btn>
        <f-btn
          appearance="primary"
          icon="add"
          :label="$t('create_issue')"
          size="sm"
          @click="createDefaults = null; showCreateDialog = true"
        />
      </div>
    </div>

    <!-- Loading state -->
    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <!-- Content area: fills remaining space -->
    <div v-else class="docnet-issue-content">
      <!-- Grouped view -->
      <div v-if="groupBy !== 'none' && groupedIssues" class="docnet-grouped-list">
        <div v-for="group in groupedIssues" :key="group.label" class="docnet-group-section">
          <div class="docnet-group-header row items-center q-py-xs q-px-sm" @click="collapsedGroups[group.label] = !collapsedGroups[group.label]">
            <q-icon :name="collapsedGroups[group.label] ? 'chevron_right' : 'expand_more'" size="20px" class="q-mr-xs" />
            <span class="text-weight-medium">{{ group.label }}</span>
            <q-badge class="q-ml-sm" color="grey-5" text-color="grey-9" :label="group.issues.length" />
            <q-space />
            <q-btn flat dense round icon="add" size="sm" @click.stop="onCreateInGroup(group.label)" />
          </div>
          <DocBitsTable
            v-if="!collapsedGroups[group.label]"
            :rows="group.issues"
            :columns="listColumns"
            row-key="id"
            dense
            flat-style
            selectable-rows="none"
            table-height=""
            table-class=""
            :features="tableFeatures"
            :pagination="{ sortBy: 'title', descending: false, page: 1, rowsPerPage: 0, rowsNumber: group.issues.length }"
            @row-click="onRowClick"
          >
            <template #body-cell-title="{ row }">
              <div class="row items-center no-wrap q-gutter-xs">
                <q-badge v-if="titlePrefix(row.title)" color="blue-grey-3" text-color="blue-grey-9" :label="titlePrefix(row.title)" />
                <span>{{ titleDisplay(row.title) }}</span>
              </div>
            </template>
            <template #body-cell-status="{ row }">
              <StatusBadge :status="row.status" />
            </template>
            <template #body-cell-priority="{ row }">
              <PriorityIcon :priority="row.priority" />
            </template>
            <template #body-cell-assignee_name="{ row }">
              <AssigneeChip :name="row.assignee_name" :type="row.assignee_type" size="sm" />
            </template>
            <template #body-cell-mission_name="{ row }">
              <div v-if="row.mission_name" class="row items-center no-wrap q-gutter-xs">
                <q-badge v-if="titlePrefix(row.mission_name)" color="blue-grey-3" text-color="blue-grey-9" :label="titlePrefix(row.mission_name)" />
                <span>{{ titleDisplay(row.mission_name) }}</span>
              </div>
            </template>
          </DocBitsTable>
        </div>
      </div>

      <!-- List view: ungrouped -->
      <DocBitsTable
        v-else
        :rows="filteredIssues"
        :columns="listColumns"
        row-key="id"
        :loading="loading"
        dense
        flat-style
        selectable-rows="none"
        table-height="100%"
        table-class=""
        pagination-label="records_per_page"
        :features="{
          sorting: true,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: false,
          resizable: false,
          pagination: true,
          columnReorder: false,
          clientSidePagination: false,
        }"
        :pagination="{
          sortBy: 'title',
          descending: false,
          page: issueStore.page,
          rowsPerPage: issueStore.pageSize,
          rowsNumber: issueStore.totalIssues,
        }"
        @row-click="onRowClick"
        @update:pagination="onPaginationChange"
      >
        <template #body-cell-title="{ row }">
          <div class="row items-center no-wrap q-gutter-xs">
            <q-badge v-if="titlePrefix(row.title)" color="blue-grey-3" text-color="blue-grey-9" :label="titlePrefix(row.title)" />
            <span>{{ titleDisplay(row.title) }}</span>
          </div>
        </template>
        <template #body-cell-status="{ row }">
          <StatusBadge :status="row.status" />
        </template>
        <template #body-cell-priority="{ row }">
          <PriorityIcon :priority="row.priority" />
        </template>
        <template #body-cell-assignee_name="{ row }">
          <AssigneeChip :name="row.assignee_name" :type="row.assignee_type" size="sm" />
        </template>
        <template #body-cell-mission_name="{ row }">
          <div v-if="row.mission_name" class="row items-center no-wrap q-gutter-xs">
            <q-badge v-if="titlePrefix(row.mission_name)" color="blue-grey-3" text-color="blue-grey-9" :label="titlePrefix(row.mission_name)" />
            <span>{{ titleDisplay(row.mission_name) }}</span>
          </div>
        </template>
      </DocBitsTable>
    </div>

    <IssueForm
      v-model="showCreateDialog"
      :task="createDefaults"
      :missions="missionOptions"
      :saving="savingIssue"
      @save="onCreateTask"
    />
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { debounce } from 'quasar';
import { useDocNetIssueStore } from 'src/store/DocNet/docnet-issues.store';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { storeToRefs } from 'pinia';
import IssueFilters from './components/IssueFilters.vue';
import IssueForm from './components/IssueForm.vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import StatusBadge from '../shared/StatusBadge.vue';
import PriorityIcon from '../shared/PriorityIcon.vue';
import AssigneeChip from '../shared/AssigneeChip.vue';
import type { DocNetIssue, DocNetIssueCreate } from 'src/@types/docnet';
import { useUserStore } from 'src/store/User/user_details.store';

export default defineComponent({
  name: 'DocNetIssueList',

  components: {
    IssueFilters,
    IssueForm,
    DocBitsTable,
    StatusBadge,
    PriorityIcon,
    AssigneeChip,
  },

  setup() {
    const issueStore = useDocNetIssueStore();
    const agentStore = useDocNetAgentStore();
    const missionStore = useDocNetMissionStore();
    const userStore = useUserStore();
    const { filteredIssues, loading, filters } = storeToRefs(issueStore);
    const { profiles } = storeToRefs(agentStore);
    const { missions } = storeToRefs(missionStore);
    return { issueStore, agentStore, missionStore, userStore, filteredIssues, loading, filters, profiles, missions };
  },

  data() {
    const issueStore = useDocNetIssueStore();
    return {
      // Mirrors issueStore.searchFilter for v-model binding; actual store
      // push happens through a 300ms debounce set up in mounted().
      searchQuery: issueStore.searchFilter,
      debouncedPushSearch: null as null | ((v: string) => void),
      showCreateDialog: false,
      savingIssue: false,
      createDefaults: null as Partial<DocNetIssue> | null,
      collapsedGroups: {} as Record<string, boolean>,
      groupBy: 'none' as 'none' | 'status' | 'priority' | 'assignee_name',
      groupOptions: [] as { label: string; value: 'status' | 'priority' | 'assignee_name' | 'none' }[],
      tableFeatures: {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: false,
        pagination: true,
        columnReorder: false,
      },
      listColumns: [] as { name: string; label: string; field: string; align: 'left'; sortable: boolean }[],
    };
  },

  computed: {
    /** My open issues — fetched server-side independent of the paginated list */
    myIssues(): DocNetIssue[] {
      return this.issueStore.myIssues;
    },

    agentOptions(): { id: string; name: string; role?: string; workload?: number }[] {
      // Orchestrators and system routers are coordination-only — issues are
      // delegated FROM them to specialist agents, never assigned TO them.
      // Excluding them from the assignee dropdowns keeps the list actionable.
      return this.profiles
        .filter(p => p.role !== 'orchestrator' && p.role !== 'router')
        .map(p => ({
          id: p.agent.id,
          name: p.agent.name,
          role: p.role,
          workload: p.workload_percent,
        }));
    },

    missionOptions(): { id: string; name: string }[] {
      return this.missions.map(m => ({ id: m.id, name: m.name }));
    },

    humanOptions(): { id: string; name: string }[] {
      // Users come from doc2-api via user_details.store.getAllUsers(),
      // the same source used by /settings/users and FormElementUserDropdown.
      // DocNet backend has no user endpoint — this is the canonical list.
      // Build a display name from first_name/last_name, falling back to
      // email so anonymous rows still render rather than showing blanks.
      const users = (this.userStore.allUsers || []) as Array<Record<string, unknown>>;
      return users
        .map((u) => {
          const first = (u.first_name as string) || '';
          const last = (u.last_name as string) || '';
          const fullName = `${first} ${last}`.trim();
          const name = fullName || (u.email as string) || (u.username as string) || '';
          return { id: String(u.id ?? ''), name };
        })
        .filter((o) => o.id && o.name);
    },

    groupedIssues(): { label: string; issues: DocNetIssue[] }[] | null {
      if (this.groupBy === 'none') return null;
      const field = this.groupBy;
      const groups = new Map<string, DocNetIssue[]>();
      for (const issue of this.filteredIssues) {
        const key = (issue as any)[field] || this.$t('docnet_unassigned');
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key)!.push(issue);
      }
      return Array.from(groups.entries()).map(([label, issues]) => ({
        label,
        issues,
      }));
    },
  },

  methods: {
    /** Extract "[PREFIX]" from an issue title for badge rendering */
    titlePrefix(title: string | undefined): string {
      const match = title?.match(/^\[([^\]]+)\]/);
      return match ? match[1] : '';
    },

    /** Issue title without the "[PREFIX]" prefix */
    titleDisplay(title: string | undefined): string {
      if (!title) return '';
      return title.replace(/^\[[^\]]+\]\s*/, '').trim();
    },

    onFiltersUpdate(newFilters: Record<string, string>) {
      Object.entries(newFilters).forEach(([key, value]) => {
        this.issueStore.setFilter(key as any, value);
      });
    },

    onSearchInput(value: string | number | null) {
      // Input v-model stays live for cursor stability; the store is pushed
      // through the 300ms debounce set up in mounted().
      const text = value == null ? '' : String(value);
      this.searchQuery = text;
      this.debouncedPushSearch?.(text);
    },

    async onClearFilters() {
      // Mirror the store reset locally so the search input clears visually.
      this.searchQuery = '';
      await this.issueStore.clearFilters();
    },

    async onPaginationChange(pagination: { page: number; rowsPerPage: number }) {
      if (pagination.rowsPerPage !== this.issueStore.pageSize) {
        this.issueStore.pageSize = pagination.rowsPerPage;
      }
      await this.issueStore.setIssuePage(pagination.page);
    },

    onIssueClick(task: DocNetIssue) {
      this.$router.push('/doc-net/issues/' + task.id);
    },

    onRowClick(event: { row: DocNetIssue; rowIndex: number }) {
      this.$router.push('/doc-net/issues/' + event.row.id);
    },

    onCreateInGroup(groupValue: string) {
      const field = this.groupBy;
      if (field !== 'none') {
        this.createDefaults = { [field]: groupValue } as Partial<DocNetIssue>;
      } else {
        this.createDefaults = null;
      }
      this.showCreateDialog = true;
    },

    async onCreateTask(data: DocNetIssueCreate) {
      this.savingIssue = true;
      try {
        await this.issueStore.createIssue(data);
        this.showCreateDialog = false;
        this.createDefaults = null;
      } catch (err: any) {
        notify.error(err?.message || this.$t('failed_to_create_issue'));
      } finally {
        this.savingIssue = false;
      }
    },

  },

  created() {
    this.groupOptions = [
      { label: this.$t('status'), value: 'status' as const },
      { label: this.$t('priority'), value: 'priority' as const },
      { label: this.$t('assignee'), value: 'assignee_name' as const },
      { label: this.$t('none'), value: 'none' as const },
    ];
    this.listColumns = [
      { name: 'title', label: this.$t('title'), field: 'title', align: 'left' as const, sortable: true },
      { name: 'status', label: this.$t('status'), field: 'status', align: 'left' as const, sortable: true },
      { name: 'priority', label: this.$t('priority'), field: 'priority', align: 'left' as const, sortable: true },
      { name: 'assignee_name', label: this.$t('assignee'), field: 'assignee_name', align: 'left' as const, sortable: false },
      { name: 'mission_name', label: this.$t('mission'), field: 'mission_name', align: 'left' as const, sortable: false },
    ];
  },

  async mounted() {
    // 300ms matches the dashboard/missions/email search-debounce cadence.
    this.debouncedPushSearch = debounce((value: string) => {
      this.issueStore.setSearchFilter(value || '');
    }, 300);

    const userId = String(this.userStore.getUserId() || '');
    await Promise.allSettled([
      this.missionStore.fetchMissions(),
      this.issueStore.fetchIssues(),
      this.issueStore.fetchMyIssues(userId),
      this.agentStore.fetchProfiles(),
      // Populate human assignee options. getAllUsers is cached + request-
      // deduped in the user store, so this is cheap on subsequent mounts.
      this.userStore.getAllUsers(),
    ]);
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().subscribe(`issues:${orgId}`);
    }
  },

  beforeUnmount() {
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().unsubscribe(`issues:${orgId}`);
    }
    // Clear the persisted search via the setter so page resets to 1 too —
    // otherwise re-entry lands on a stale page with no visible search term.
    // Fire-and-forget; the refetch is harmless since the component is
    // unmounting.
    if (this.issueStore.searchFilter) {
      void this.issueStore.setSearchFilter('');
    }
  },
});
</script>

